rows=[]
def row(id,aspect,status,paper,training,inference,discrepancy,evidence,uncertainty=''):
 rows.append(dict(id=id,aspect=aspect,status=status,paper_definition=paper,checkpoint_training_evidence=training,current_inference=inference,discrepancy=discrepancy,evidence_ids=evidence,uncertainty=uncertainty))
row('state','state representation','PARTIAL','形式状态=当前 LLM context + paper queue；Sq 为 query-only，Sq+p 为 query+当前论文元信息。并未明确整个 queue 被序列化成 token。','公开训练 prompt 为 query-only 或 query+title+abstract+section names；结果论文用于下一 session。','Python 保存 queue/touch_ids/score/树；Crawler 输入只有 query 或 query+单篇论文元信息，无队列全集、分数、剩余预算。','环境 state 与模型可见 observation 不等价；不能把 Python 内存在的数据算成 Crawler 看见的数据。',['P_STATE','P_RETURN','T_DATA','T_NEXT','C_INIT','C_CONTEXT','C_PROMPT'])
row('actions','action space','PARTIAL','token-level action 是词表；工具层函数为 Search、Expand、Stop。','按外部 typ 只解析 Search 或 Expand；StopSearch/StopExpand 被 reward handler 识别。','Search 阶段只提取 Search 文本；Expand 阶段只提取 Expand 文本；没有统一三动作 dispatcher。','声明的函数接口比实际可执行接口宽；标记也不是单独新增 special token 的证据。',['P_STATE','P_FUN','T_ACTION','T_REWARD','C_INIT','C_SEARCH','C_DOEXP'])
row('search_decision','Search 决策','PARTIAL','根据当前 context 生成 query 调用 Search；训练协议从 Sq 开始。','先产生整个 Search session，再 rollout；正常路径随后只构造 Expand session。','run 固定先且仅调用一次 search；模型决定 query 文本及可解析数量，不能在 Expand 后重启 Search。','阶段调度由 Python 决定；论文方法层未明确禁止回搜，但训练描述不支持宣称已学会回搜。',['P_FUN','P_SFT','T_LOOP','C_RUN','C_SEARCH'])
row('query_generation','query generation','MATCH','Search session 是多条互补 query 的序列；偏好 survey 是公开 prompt 的一部分。','GPT-4o 合成 query 列表再串接 Search 标记；公开训练 prompt 与当前 prompt 同型。','一次 infer 自回归生成多个 query，regex 后取至多 search_queries=5；尚无外部检索反馈。','MATCH 仅指多 query session 生成；不表示 query 质量、固定五条或工具交互能力一致。',['P_SFT','T_DATA','C_SEARCH','C_INFER','C_PROMPT'])
row('feedback','retrieval feedback','PARTIAL','结果入 queue，下一 paper session 的输入依赖检索结果；同一 Search session 是否注入逐次结果未明确。','batch_generation 先完成，rollout 后执行 Search；下一轮看到新论文元信息而非上一页完整 SERP。','Search 结果转成论文对象；后续 Expand 看单篇 title/abstract/section keys，初始 query 生成不会被结果修订。','有跨 session 结果条件化；没有同 session 的 search→observation→requery 接口。',['P_RETURN','P_SFT','T_LOOP','T_NEXT','C_SEARCH','C_CONTEXT','C_GOOGLE'],'论文的通用 state 定义不足以证明具体 SERP observation schema。')
row('alternation','Search/Expand 是否可交替','UNCLEAR','一条任务轨迹包含 Search 和 Expand 已明确；是否支持同 session 混合或 Expand→Search→Expand 自由交替未明确。','模板分 Search/Expand 两种；正常 PPO 调度 Search→Expand→Expand。没有受反馈驱动的混合动作训练证据。','严格 Search phase→若干 Expand layers，没有回 Search 的边。','当前代码不支持自由交替是确定事实；把它命名为恢复论文已证明的交替能力则证据不足。',['P_FUN','P_SFT','P_PPO','T_LOOP','T_ACTION','C_RUN'],'UNCLEAR 指论文是否要求/实现自由交替，不是代码调用链不清楚。')
row('subsection','subsection selection','PARTIAL','模型选 subsection name；工具把该 subsection 引用论文入队。','SFT 按引用命中 GT/10% 多样性选择；公开训练按规范化章节名匹配。','模型选 keys；仅 exact section name 生效，程序展开该节引用标题，再解析、去重、评分。','保留核心选择机制；完整引用入队受元数据可用性、本地 resolver、名称匹配限制。',['P_FUN','P_SFT','T_ACTION','C_CONTEXT','C_DOEXP','C_REF','C_TITLE'])
row('queue','paper queue','PARTIAL','Search/Expand 追加结果；Stop 换下一 paper；Eq.(2) 依全局 Qt 去重。','公开 reward 的 searched_paper_set 在每次 response_handler 内新建；下一批论文由 reward/prob 排序取六条。','queue 为分层列表；以 Selector 分数排序新 frontier；第一层全取，之后最多20，指针越过未取项。','不是逐 Stop 驱动的可持续消费队列；训练局部去重也不等于论文全局 Qt。',['P_FUN','P_RETURN','T_REWARD','T_NEXT','C_EXPAND','C_NODE'])
row('stop','Stop 语义','MISSING','结束当前 session：query-only 时结束搜索 session，paper session 时结束当前 paper；context reset 到 query+下一 paper。','训练识别 StopSearch/StopExpand 并给 stop 位置奖励；不是 global Finish。','没有 Stop parser 或分支；生成由 EOS/token cap 结束，Python 固定执行后续调度；空 Expand 列表仅间接跳过该 paper。','缺失的是 Stop 的显式运行时语义，不是说模型不会输出停止标记或不能少选章节。',['P_FUN','P_RETURN','T_REWARD','C_INFER','C_BATCH','C_DOEXP','C_RUN'])
row('finish','global Finish','MATCH','未定义明确的可学习 global Finish；Stop 不等于任务完成，实践另有深度限制。','未见 global Finish 动作或模型输入的总预算；训练以 rounds/长度等外部界限截止。','run 在固定 layers 迭代后返回；模型无整体结束任务动作。','共同缺席（MATCH_ABSENCE）；不能作为已有 Finish 的恢复。',['P_FUN','P_SETUP','P_PPO','T_LOOP','T_CONFIG','C_RUN'],'论文对 queue 耗尽等所有边界情况没有完整状态机规格。')
row('budget','budget awareness','PARTIAL','cost 是优化目标中的软惩罚；§5.2 有外部探索深度上限，不等于显式剩余预算状态。','rounds、max_action、response_length 等外部限制；未见面向模型的 global budget 字段。','search_queries/search_papers/expand_layers/expand_papers/max_new_tokens 是外部上限，没有预算 observation。','两侧均有资源限制，均不能据此声称 budget-aware policy；运行时预算感知是未见于这些证据的新机制。',['P_REWARD','P_SETUP','P_PPO','T_ACTION','T_LOOP','T_CONFIG','C_INIT','C_INFER'])
row('cost','action cost','PARTIAL','r=α·新增相关论文数−c；Search/Expand=0.1，Stop=0；附录 G.2 验证降低无效动作。','README 覆盖参数匹配论文；公开 handler 又含截断、+cost stop shaping、局部去重和 Selector stub。','不在线计算 cost 或 reward；训练影响可能保留在输出中；metrics.py 的−0.1是离线统计。','无运行时 cost 不是 RL policy 失效的证据；公开训练 reward 不是论文公式的逐项等价实现。',['P_REWARD','P_PPO','P_COST','T_REWARD','T_STUB','C_RECIPE','C_METRICS'])
row('feedback_loop','multi-step feedback loop','PARTIAL','通过新论文 session 连续探索引用网络；跨 session value 为长期信用分配。','有下一轮 paper-context 条件化；无 session 内执行一步再生成一步的外部反馈。','后层 prompt 依赖前层找到的论文，所以不是完全无反馈；反馈仅在固定分层的论文元信息上。','不能称当前 PaSa 完全没有 multi-step；缺少的是统一、可变调度的逐工具反馈闭环。',['P_RETURN','T_LOOP','T_NEXT','C_CONTEXT','C_EXPAND','C_RUN'])
row('trajectory','trajectory execution','PARTIAL','概念上 token MDP + session 分割；展示模板为同类动作串。','先 generate 整串再解析执行，与推理批量阶段具有结构相似性。','两处 generate 都先返回整串，后执行匹配动作；不按文本中的 Search/Expand/Stop 全局顺序解释。','概念 token action 执行叙述与实现 generate-then-execute 不等价；也不能把阶段化全部归咎于当前本地补丁。',['P_STATE','P_FUN','P_SFT','T_LOOP','C_SEARCH','C_DOEXP','C_INFER'])
row('autonomy','inference-time policy autonomy','PARTIAL','模型决定查询与章节，并通过 RL 优化发现相关论文；论文的广义自主描述不能代替具体控制协议。','支持两类 session 技能和跨 session value 学习；精确 checkpoint 的任意混合/预算/重查询能力未经证明。','自主部分=生成 query/选章节/输出数量；调度类型、队列排序、深度、截止、TopK、工具与 Page1 由代码决定。','局部策略自主存在，整体调度自主受限。',['P_FUN','P_SFT','P_RETURN','T_LOOP','C_RUN','C_EXPAND','C_GOOGLE'])
row('long_term','cross-session long-term value','PARTIAL','Eq.(3) 已把新论文的下一 session 估值加入 return，允许经不直接相关论文寻找后续相关文献。','call_vm 估计论文 prompt 的值，handler 加 gamma1·value；训练代码的采样/截断另有限制。','只加载 Crawler/Selector；queue 按 Selector 当前相关性排序，不在推理时调用 value head。','长期价值学习本身已属 PaSa；运行时显式长期价值调度并非当前实现，也不能宣称模型完全没有长期倾向。',['P_RETURN','P_FUN','T_VM','T_REWARD','C_ENTRY','C_EXPAND','C_NODE'])
