out={'audit':'PASA_CRAWLER_MECHANISM_AUDIT_001','scope':'Static analysis only; no model execution, training or new retrieval experiment.','comparison_baseline':'ACL 2025 final, public training source pinned at 7a266d8, local inference at fe89b48','status_legend':{'MATCH':'Specified narrow mechanism agrees; for global Finish, both explicitly lack that defined feature (MATCH_ABSENCE).','PARTIAL':'Core concept partly represented but observation/execution/scope differs; does not assert missing training capability.','MISSING':'Explicit runtime mechanism absent despite paper definition.','UNCLEAR':'Primary sources do not establish the claimed paper/checkpoint capability; code behavior may still be definite.'},'checkpoint_caveat':'Public recipe/source and model card do not prove exact checkpoint training provenance or behavior. Released SFT file could not be downloaded (HTTP 401).','evidence_catalog':E,'items':rows}
